<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Sorting Algorithm Visualizer</title>
    <style>
        :root {
            --bg-color: #121212;
            --text-color: #e0e0e0;
            --bar-color: #4caf50;
            --highlight-compare: #ff9800;
            --highlight-swap: #f44336;
            --button-bg: #333;
            --button-hover: #444;
        }

        body {
            font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
            background-color: var(--bg-color);
            color: var(--text-color);
            margin: 0;
            padding: 20px;
            display: flex;
            flex-direction: column;
            align-items: center;
        }

        h1 {
            margin-bottom: 20px;
        }

        .controls {
            margin-bottom: 20px;
            display: flex;
            gap: 10px;
        }

        button {
            padding: 10px 20px;
            background-color: var(--button-bg);
            color: white;
            border: none;
            border-radius: 5px;
            cursor: pointer;
            font-size: 16px;
            transition: background-color 0.2s;
        }

        button:hover {
            background-color: var(--button-hover);
        }

        #bars-container {
            display: flex;
            align-items: flex-end;
            justify-content: center;
            width: 90%;
            max-width: 800px;
            height: 300px;
            padding: 20px;
            background-color: #1e1e1e;
            border-radius: 5px;
            margin-bottom: 20px;
        }

        .bar {
            flex: 1;
            margin: 0 2px;
            background-color: var(--bar-color);
            border-radius: 3px 3px 0 0;
            transition: height 0.3s ease, background-color 0.2s ease;
            min-width: 5px;
        }

        .compare {
            background-color: var(--highlight-compare) !important;
        }

        .swap {
            background-color: var(--highlight-swap) !important;
        }
    </style>
</head>
<body>
    <h1>Sorting Algorithm Visualizer</h1>

    <div class="controls">
        <button id="sort">Sort Array</button>
        <button id="shuffle">Shuffle</button>
        <button id="reset">Reset</button>
    </div>

    <div id="bars-container"></div>

    <script>
        // Default array size and values
        const DEFAULT_SIZE = 30;
        let originalArray = [];

        // Sorting state
        let currentArray = [];
        let isSorting = false;
        let sortGenerator = null;

        // DOM elements
        const barsContainer = document.getElementById('bars-container');
        const sortButton = document.getElementById('sort');
        const shuffleButton = document.getElementById('shuffle');
        const resetButton = document.getElementById('reset');

        // Initialize the visualizer with a default array
        function init() {
            originalArray = Array.from({length: DEFAULT_SIZE}, (_, i) => Math.floor(Math.random() * 100) + 1);
            setArray([...originalArray]);
        }

        // Create bars in the container
        function renderBars() {
            barsContainer.innerHTML = '';

            currentArray.forEach(value => {
                const bar = document.createElement('div');
                bar.className = 'bar';
                // Set height based on value (normalized to max 100)
                const heightPercentage = (value / 150) * 100; 
                bar.style.height = `${Math.max(heightPercentage, 2)}%`;
                barsContainer.appendChild(bar);
            });
        }

        // Update a specific bar's height
        function updateBar(index, value) {
            if (index >= 0 && index < currentArray.length) {
                const bar = barsContainer.children[index];
                const heightPercentage = (value / 150) * 100;
                bar.style.height = `${Math.max(heightPercentage, 2)}%`;
            }
        }

        // Highlight bars for comparison or swapping
        function highlightBars(indices, className) {
            indices.forEach(index => {
                if (index >= 0 && index < currentArray.length) {
                    const bar = barsContainer.children[index];
                    bar.classList.add(className);
                    setTimeout(() => {
                        if (bar) {
                            bar.classList.remove(className);
                        }
                    }, 300);
                }
            });
        }

        // Check if the array is sorted
        function isSorted() {
            for (let i = 1; i < currentArray.length; i++) {
                if (currentArray[i] < currentArray[i - 1]) {
                    return false;
                }
            }
            return true;
        }

        // Generator for bubble sort
        function* bubbleSortGenerator(arr) {
            const arrayCopy = [...arr];
            const n = arrayCopy.length;

            for (let i = 0; i < n - 1; i++) {
                for (let j = 0; j < n - i - 1; j++) {
                    // Highlight comparison
                    highlightBars([j, j + 1], 'compare');

                    yield { type: 'compare', indices: [j, j + 1] };

                    if (arrayCopy[j] > arrayCopy[j + 1]) {
                        // Swap elements
                        const temp = arrayCopy[j];
                        arrayCopy[j] = arrayCopy[j + 1];
                        arrayCopy[j + 1] = temp;

                        updateBar(j, arrayCopy[j]);
                        updateBar(j + 1, arrayCopy[j + 1]);

                        highlightBars([j, j + 1], 'swap');
                        yield { type: 'swap', indices: [j, j + 1] };
                    }
                }
            }

            return true;
        }

        // Generator for insertion sort (alternative)
        function* insertionSortGenerator(arr) {
            const arrayCopy = [...arr];
            const n = arrayCopy.length;

            for (let i = 1; i < n; i++) {
                let key = arrayCopy[i];
                let j = i - 1;

                while (j >= 0 && arrayCopy[j] > key) {
                    highlightBars([j, j + 1], 'compare');
                    yield { type: 'compare', indices: [j, j + 1] };

                    arrayCopy[j + 1] = arrayCopy[j];
                    updateBar(j + 1, arrayCopy[j + 1]);
                    if (j !== i - 1) {
                        highlightBars([j, j + 1], 'swap');
                    }
                    yield { type: 'move', indices: [j, j + 1] };

                    j--;
                }

                arrayCopy[j + 1] = key;
                updateBar(j + 1, arrayCopy[j + 1]);
            }

            return true;
        }

        // Generator for merge sort (top-down)
        function* mergeSortGenerator(arr) {
            const arrayCopy = [...arr];
            yield* mergeSortHelper(arrayCopy, 0, arrayCopy.length - 1);
            return true;
        }

        function* mergeSortHelper(array, left, right) {
            if (left < right) {
                const mid = Math.floor((left + right) / 2);

                yield* mergeSortHelper(array, left, mid);
                yield* mergeSortHelper(array, mid + 1, right);

                // Merge step
                let i = left;
                let j = mid + 1;
                let k = left;
                const temp = [];

                while (i <= mid && j <= right) {
                    highlightBars([i, j], 'compare');
                    yield { type: 'compare', indices: [i, j] };

                    if (array[i] <= array[j]) {
                        temp.push(array[i]);
                        i++;
                    } else {
                        temp.push(array[j]);
                        j++;
                    }
                }

                while (i <= mid) {
                    temp.push(array[i]);
                    i++;
                }

                while (j <= right) {
                    temp.push(array[j]);
                    j++;
                }

                for (let p = 0; p < temp.length; p++) {
                    array[left + p] = temp[p];
                    updateBar(left + p, array[left + p]);
                    highlightBars([left + p], 'swap');
                    yield { type: 'update', index: left + p };
                }
            }
        }

        // Generator for quick sort
        function* quickSortGenerator(arr) {
            const arrayCopy = [...arr];
            yield* quickSortHelper(arrayCopy, 0, arrayCopy.length - 1);
            return true;
        }

        function* quickSortHelper(array, low, high) {
            if (low < high) {
                let pi = yield* partition(array, low, high);

                yield* quickSortHelper(array, low, pi - 1);
                yield* quickSortHelper(array, pi + 1, high);
            }
        }

        function* partition(array, low, high) {
            const pivot = array[high];
            let i = low - 1;

            for (let j = low; j < high; j++) {
                highlightBars([j, high], 'compare');
                yield { type: 'compare', indices: [j, high] };

                if (array[j] <= pivot) {
                    i++;

                    // Swap array[i] and array[j]
                    const temp = array[i];
                    array[i] = array[j];
                    array[j] = temp;

                    updateBar(i, array[i]);
                    updateBar(j, array[j]);

                    highlightBars([i, j], 'swap');
                    yield { type: 'swap', indices: [i, j] };
                }
            }

            // Swap array[i + 1] and array[high]
            const temp = array[i + 1];
            array[i + 1] = array[high];
            array[high] = temp;

            updateBar(i + 1, array[i + 1]);
            updateBar(high, array[high]);

            highlightBars([i + 1, high], 'swap');
            yield { type: 'swap', indices: [i + 1, high] };

            return i + 1;
        }

        // Generator for selection sort
        function* selectionSortGenerator(arr) {
            const arrayCopy = [...arr];
            const n = arrayCopy.length;

            for (let i = 0; i < n - 1; i++) {
                let minIndex = i;

                for (let j = i + 1; j < n; j++) {
                    highlightBars([minIndex, j], 'compare');
                    yield { type: 'compare', indices: [minIndex, j] };

                    if (arrayCopy[j] < arrayCopy[minIndex]) {
                        minIndex = j;
                    }
                }

                // Swap found minimum with first element
                if (minIndex !== i) {
                    const temp = arrayCopy[i];
                    arrayCopy[i] = arrayCopy[minIndex];
                    arrayCopy[minIndex] = temp;

                    updateBar(i, arrayCopy[i]);
                    updateBar(minIndex, arrayCopy[minIndex]);

                    highlightBars([i, minIndex], 'swap');
                    yield { type: 'swap', indices: [i, minIndex] };
                }
            }

            return true;
        }

        // Set the sorting algorithm (default to bubble sort)
        function setSortAlgorithm(algorithm = 'bubble') {
            if (algorithm === 'bubble') {
                sortGenerator = bubbleSortGenerator(currentArray);
            } else if (algorithm === 'insertion') {
                sortGenerator = insertionSortGenerator(currentArray);
            } else if (algorithm === 'merge') {
                sortGenerator = mergeSortGenerator(currentArray);
            } else if (algorithm === 'quick') {
                sortGenerator = quickSortGenerator(currentArray);
            } else if (algorithm === 'selection') {
                sortGenerator = selectionSortGenerator(currentArray);
            }
        }

        // Sort step function
        function sortStep() {
            if (!sortGenerator || isSorting) return false;

            const result = sortGenerator.next();
            isSorting = !result.done;  // Continue sorting until done

            // Check for completion after a short delay to allow UI updates
            setTimeout(() => {
                if (isSorting && sortGenerator) {
                    sortStep();
                } else {
                    // Sort is complete
                    highlightBars([], '');  // Clear all highlights
                }
            }, 10);  // Small delay to ensure UI rendering

            return result.done;
        }

        // Shuffle the array randomly using Fisher-Yates shuffle
        function shuffle() {
            const newArray = [...currentArray];

            for (let i = newArray.length - 1; i > 0; i--) {
                const j = Math.floor(Math.random() * (i + 1));
                [newArray[i], newArray[j]] = [newArray[j], newArray[i]];
            }

            currentArray = newArray;
            renderBars();
        }

        // Reset to the original array
        function reset() {
            setArray([...originalArray]);
            sortGenerator = null;
            isSorting = false;
        }

        // Set a new array and redraw
        function setArray(newArray) {
            currentArray = [...newArray];
            originalArray = [...newArray];  // Store as original for reset
            renderBars();

            if (isSorting && sortGenerator) {
                // If sorting is in progress, restart with the new array
                sortGenerator = null;
                isSorting = false;
            }
        }

        // Get current array
        function getArray() {
            return [...currentArray];
        }

        // Initialize UI event handlers
        function initEventListeners() {
            sortButton.addEventListener('click', () => {
                if (!isSorting) {
                    setSortAlgorithm('bubble');  // Default to bubble sort
                    isSorting = true;
                    sortStep();
                }
            });

            shuffleButton.addEventListener('click', shuffle);

            resetButton.addEventListener('click', reset);
        }

        // Initialize the visualizer
        window.onload = function() {
            init();
            initEventListeners();

            // Expose API to window.viz
            window.viz = {
                array: getArray,
                setArray: setArray,
                sortStep: sortStep,
                sorted: isSorted
            };
        };
    </script>
</body>
</html>
